/* aj_agent.js — AJ agent brain (generated by agent/train.py; do not hand-edit the DATA blob)
   Pipeline: perceive -> classify (~100k-param net, trained from scratch) -> RAG retrieve -> pick tool -> act -> reflect.
   No external dependencies. */
(function () {
  const D = /*__DATA__*/null;
  const F = D.F, H = D.H, C = D.C;

  // ---- identical featurizer to train.py ----
  const enc = new TextEncoder();
  function fnv(s) {
    let h = 0x811c9dc5;
    for (const b of enc.encode(s)) { h ^= b; h = Math.imul(h, 0x01000193) >>> 0; }
    return h >>> 0;
  }
  function feats(text) {
    const t = text.toLowerCase().replace(/[^a-z0-9\u0b80-\u0bff' ]+/g, " ");
    const words = t.split(/\s+/).filter(Boolean);
    const d = new Map();
    const add = (k) => { const i = fnv(k) % F; d.set(i, (d.get(i) || 0) + 1); };
    for (const w of words) {
      add("w:" + w);
      const p = "<" + w + ">";
      for (let j = 0; j < p.length - 2; j++) add("c:" + p.slice(j, j + 3));
    }
    for (let i = 0; i < words.length - 1; i++) add("b:" + words[i] + "_" + words[i + 1]);
    let n = 0; for (const v of d.values()) n += v * v;
    n = Math.sqrt(n) || 1;
    const idx = [], val = [];
    for (const [i, v] of d) { idx.push(i); val.push(v / n); }
    return { idx, val };
  }

  // ---- model (int8 weights) ----
  const b64 = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
  const W1 = new Int8Array(b64(D.w1).buffer), W2 = new Int8Array(b64(D.w2).buffer);
  function classify(text) {
    const { idx, val } = feats(text);
    const h = new Float32Array(H);
    for (let k = 0; k < idx.length; k++) {
      const row = idx[k] * H, v = val[k] * D.s1;
      for (let j = 0; j < H; j++) h[j] += v * W1[row + j];
    }
    for (let j = 0; j < H; j++) h[j] = Math.max(0, h[j] + D.b1[j]);
    const z = new Float32Array(C);
    for (let c = 0; c < C; c++) {
      let s = D.b2[c];
      for (let j = 0; j < H; j++) s += h[j] * W2[j * C + c] * D.s2;
      z[c] = s;
    }
    const mx = Math.max(...z); let sum = 0;
    for (let c = 0; c < C; c++) { z[c] = Math.exp(z[c] - mx); sum += z[c]; }
    let best = 0;
    for (let c = 0; c < C; c++) { z[c] /= sum; if (z[c] > z[best]) best = c; }
    return { intent: D.classes[best], confidence: z[best], probs: z };
  }

  // ---- RAG: cosine retrieval over the prompt DB + knowledge chunks ----
  function build(items) { return items.map((it) => ({ it, f: feats(it.text) })); }
  const promptIdx = build(D.phrases.map(([text, y]) => ({ text, intent: D.classes[y] })));
  const kbIdx = build(D.knowledge.map((text) => ({ text })));
  function retrieve(index, query, k) {
    const q = feats(query), qv = new Map(q.idx.map((i, n) => [i, q.val[n]]));
    const scored = index.map(({ it, f }) => {
      let s = 0; for (let n = 0; n < f.idx.length; n++) { const v = qv.get(f.idx[n]); if (v) s += v * f.val[n]; }
      return { ...it, score: s };
    });
    return scored.sort((a, b) => b.score - a.score).slice(0, k);
  }

  // ---- local state (user's own data only) ----
  const T0 = Date.now();
  const store = {
    get(k, d) { try { return JSON.parse(localStorage.getItem("aj_agent_" + k)) ?? d; } catch (e) { return d; } },
    set(k, v) { try { localStorage.setItem("aj_agent_" + k, JSON.stringify(v)); } catch (e) {} },
  };
  const pick = (a) => a[Math.floor(Math.random() * a.length)];
  const U = () => (window.AJ_AI && AJ_AI.config && AJ_AI.config.userName) || "BOSS";

  // ---- tools: each returns a string, or null to hand off (reflection step) ----
  const tools = {
    persona(text, ctx) {
      const g = { greetings: [`Online, ${U()}. Standing by.`, `Here and ready, ${U()}.`, `Systems green. What's the move, ${U()}?`],
        jarvis_formal_commands: [`Understood, ${U()}. Logged and prioritised.`, `On it. I'll keep you posted.`, `Acknowledged. Queued for your review.`],
        system_flavor: [`Done — interface updated.`, `Display state applied.`, `Acknowledged. Cosmetic change only; nothing external touched.`] };
      return pick(g[ctx.intent] || g.greetings);
    },
    clock(text) {
      const n = new Date();
      if (/\b(date|day|today)\b/i.test(text) && !/\btime\b/i.test(text)) return n.toLocaleDateString(undefined, { weekday: "long", year: "numeric", month: "long", day: "numeric" });
      if (/\b(time|clock)\b/i.test(text)) return n.toLocaleTimeString();
      return null;
    },
    status(text) {
      const mins = Math.round((Date.now() - T0) / 60000);
      return `Session ${mins} min. Brain: ${H * F + H + H * C + C} params, ${C} intents. Memory: ${(window.AJ_AI && AJ_AI.memory ? AJ_AI.memory.length : 0)} turns. Notes: ${store.get("notes", []).length}.`;
    },
    notes(text) {
      const notes = store.get("notes", []);
      if (/\b(show|list|read|what)\b/i.test(text)) return notes.length ? notes.slice(-5).map((n, i) => `${i + 1}. ${n.text}`).join("\n") : "No notes yet.";
      if (/\b(clear|delete)\b/i.test(text)) { store.set("notes", []); return "Notes cleared."; }
      const body = text.replace(/^(aj,?\s*)?(please\s*)?(log|note down|note|save|remind me( to)?|set a reminder( to| for)?|add)\s+/i, "").trim();
      if (!body) return null;
      notes.push({ text: body, at: new Date().toISOString() }); store.set("notes", notes);
      return `Saved: "${body}". (Stored locally on this device.)`;
    },
  };

  const ROUTE = { // intent -> tool (anything else goes to RAG+LLM)
    greetings: "persona", jarvis_formal_commands: "persona", system_flavor: "persona",
    status_diagnostics: "status", scheduling_reminders: "notes", personal_admin_lifestyle: "notes", workshop_studio_ops: "notes",
  };
  const THRESH = 0.45;
  // Hard rules beat the net on keywords it is known to be weak on.
  const RULES = [
    [/\b(remind me|set a reminder|set an alarm|wake me)\b/i, "scheduling_reminders"],
    [/^\s*(aj,?\s*)?translate\b|\bhow do you say\b.*\bin\b/i, "translation_language"],
  ];

  async function llm(text, ctx, context) {
    const res = await fetch(ctx.proxyURL || "/api/chat", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ input: text, history: ctx.history || [], context }),
    });
    if (!res.ok) throw new Error("proxy " + res.status);
    return (await res.json()).text;
  }

  async function run(input, ctx = {}) {
    const trace = [];
    const c = classify(input);
    trace.push({ step: "classify", intent: c.intent, confidence: +c.confidence.toFixed(3) });
    const hits = retrieve(promptIdx, input, 3), docs = retrieve(kbIdx, input, 2).filter((d) => d.score > 0.12);
    trace.push({ step: "retrieve", similar: hits.map((h) => [h.text, h.intent, +h.score.toFixed(2)]), docs: docs.length });

    let intent = c.intent;
    for (const [re, forced] of RULES) if (re.test(input)) { intent = forced; trace.push({ step: "rule", forced }); break; }
    if (c.confidence < THRESH && hits[0] && hits[0].score > 0.6) intent = hits[0].intent; // retrieval tie-break

    let text = null, tool = null;
    if (/\b(what('?s| is) the (time|date)|time now|what day is it|today'?s date|current time)\b/i.test(input)) {
      tool = "clock"; text = tools.clock(input); trace.push({ step: "tool", tool, handled: text !== null });
    }
    if (text === null && intent !== "llm_fallback" && (c.confidence >= THRESH * 0.8 || intent !== c.intent)) {
      tool = ROUTE[intent];
      if (tool) { try { text = tools[tool](input, { intent }); } catch (e) { text = null; } }
      trace.push({ step: "tool", tool: tool || "none", handled: text !== null });
    }
    if (text === null) { // reflect: tool declined or no tool -> RAG + LLM
      const context = [...docs.map((d) => d.text), ...hits.filter((h) => h.score > 0.5).map((h) => `Related request (${h.intent}): ${h.text}`)].join("\n").slice(0, 1400);
      try { text = await llm(input, ctx, context); tool = "rag_llm"; }
      catch (e) { text = "Backend unreachable. Local core only — try a status, note, or time command."; tool = "offline"; }
      trace.push({ step: "llm", tool });
    }
    return { text, intent, confidence: c.confidence, tool, trace };
  }

  window.AJ_AGENT = { run, classify, retrieve: (q, k = 3) => retrieve(promptIdx, q, k), params: H * F + H + H * C + C, classes: D.classes };
})();
